class Solution {
    public int maxDistance(java.util.List<java.util.List<Integer>> arrays) {
        int globalMin = arrays.get(0).get(0);
        int globalMax = arrays.get(0).get(arrays.get(0).size() - 1);
        int result = 0;
        for (int i = 1; i < arrays.size(); i++) {
            java.util.List<Integer> arr = arrays.get(i);
            int curMin = arr.get(0);
            int curMax = arr.get(arr.size() - 1);
            result = Math.max(result, Math.abs(curMax - globalMin));
            result = Math.max(result, Math.abs(globalMax - curMin));
            globalMin = Math.min(globalMin, curMin);
            globalMax = Math.max(globalMax, curMax);
        }
        return result;
    }
}

class Solution {
    public int maxDistance(java.util.List<java.util.List<Integer>> arrays) {
        int m = arrays.size();
        int[][] minArr = new int[m][2];
        int[][] maxArr = new int[m][2];
        for (int i = 0; i < m; i++) {
            java.util.List<Integer> arr = arrays.get(i);
            minArr[i] = new int[]{arr.get(0), i};
            maxArr[i] = new int[]{arr.get(arr.size() - 1), i};
        }
        java.util.Arrays.sort(minArr, (a, b) -> a[0] - b[0]);
        java.util.Arrays.sort(maxArr, (a, b) -> b[0] - a[0]);
        if (minArr[0][1] != maxArr[0][1]) {
            return maxArr[0][0] - minArr[0][0];
        }
        return Math.max(maxArr[0][0] - minArr[1][0], maxArr[1][0] - minArr[0][0]);
    }
}
